from pathlib import Path
ROOT=Path.cwd()
MODULE="qseries_v2/oracle_source_network/providers/uniform_sports_provider.py"
TEST="test_osn_077_uniform_canonical_sports_provider_contract_REBUILD.py"
MODULE_SOURCE='\nfrom pathlib import Path\nfrom dataclasses import dataclass\nfrom datetime import datetime, timezone\nimport contextlib, importlib, io, json, runpy, sys, urllib.request\n\nROOT = Path(__file__).resolve().parents[3]\nADMITTED=("NFL","NCAAF","NBA","NHL","MLS","EPL")\nPROMOTED={\n    "NHL":"qseries_v2/oracle_source_network/providers/production_surfaces/nhl_proven_surface.py",\n    "MLS":"qseries_v2/oracle_source_network/providers/production_surfaces/mls_proven_surface.py",\n    "EPL":"qseries_v2/oracle_source_network/providers/production_surfaces/epl_proven_surface.py",\n}\n\n@dataclass(frozen=True)\nclass CanonicalProviderResult:\n    league:str\n    events:tuple\n    event_count:int\n    authority:str\n    execution_authority:bool=False\n\ndef _events(value):\n    from qseries_v2.oracle_source_network.canonical.sports_event_v2 import CanonicalSportsEvent\n    if isinstance(value,CanonicalSportsEvent):\n        return (value,)\n    if isinstance(value,(list,tuple,set)):\n        out=[]\n        for x in value: out.extend(_events(x))\n        return tuple(out)\n    if isinstance(value,dict):\n        out=[]\n        for x in value.values(): out.extend(_events(x))\n        return tuple(out)\n    return ()\n\ndef _body(raw):\n    if isinstance(raw,(str,bytes,bytearray)): return raw\n    if isinstance(raw,dict):\n        for k in ("body","raw","html","text","content","payload"):\n            if isinstance(raw.get(k),(str,bytes,bytearray)): return raw[k]\n    for k in ("body","raw","html","text","content","payload"):\n        if hasattr(raw,k) and isinstance(getattr(raw,k),(str,bytes,bytearray)):\n            return getattr(raw,k)\n    raise RuntimeError("physical acquisition returned no exact text body")\n\ndef _legacy(league,timeout):\n    if league=="NFL":\n        from qseries_v2.oracle_source_network.acquisition.nfl_official_live import acquire_nfl_scores\n        from qseries_v2.oracle_source_network.mapping.nfl_live_escaped_state_extractor import extract_nfl_live_events\n        raw=acquire_nfl_scores(timeout=timeout)\n        value=extract_nfl_live_events(_body(raw))\n    elif league=="NCAAF":\n        from qseries_v2.oracle_source_network.acquisition.ncaa_football_official_live import acquire_ncaa_fbs_scoreboard\n        from qseries_v2.oracle_source_network.mapping.ncaaf_exact_scoreboard_extractor import extract_ncaaf_live_events\n        raw=acquire_ncaa_fbs_scoreboard(timeout=timeout)\n        value=extract_ncaaf_live_events(_body(raw))\n    elif league=="NBA":\n        from qseries_v2.oracle_source_network.acquisition.nba_official_live import acquire_nba_games\n        from qseries_v2.oracle_source_network.mapping.basketball_event_extractor import extract_basketball_events\n        raw=acquire_nba_games(timeout=timeout)\n        value=extract_basketball_events(_body(raw), "NBA", "nba_official")\n    else:\n        raise RuntimeError(league)\n    ev=_events(value)\n    if not ev: raise RuntimeError(f"{league} direct canonical chain returned zero events")\n    return CanonicalProviderResult(league,ev,len(ev),"EXACT_DIRECT_SOURCE_EXTRACTOR")\n\ndef _promoted(league,timeout,root=None):\n    base=Path(root or ROOT)\n    p=base/PROMOTED[league]\n    if not p.exists(): raise RuntimeError(f"{league} promoted source missing: {p}")\n\n    canonical=importlib.import_module("qseries_v2.oracle_source_network.canonical.sports_event_v2")\n    original_cls=canonical.CanonicalSportsEvent\n    captured=[]\n    def capture_ctor(*args,**kwargs):\n        ev=original_cls(*args,**kwargs)\n        captured.append(ev)\n        return ev\n\n    original_urlopen=urllib.request.urlopen\n    def capped_urlopen(url,*args,**kwargs):\n        if "timeout" in kwargs:\n            kwargs["timeout"]=min(float(kwargs["timeout"]),float(timeout))\n        elif len(args)>=2:\n            args=list(args); args[1]=min(float(args[1]),float(timeout)); args=tuple(args)\n        else:\n            kwargs["timeout"]=float(timeout)\n        return original_urlopen(url,*args,**kwargs)\n\n    canonical.CanonicalSportsEvent=capture_ctor\n    urllib.request.urlopen=capped_urlopen\n    buf=io.StringIO()\n    try:\n        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):\n            try:\n                runpy.run_path(str(p),run_name="__main__")\n            except SystemExit as exc:\n                if exc.code not in (None,0):\n                    raise\n    finally:\n        canonical.CanonicalSportsEvent=original_cls\n        urllib.request.urlopen=original_urlopen\n\n    # Preserve constructor order but remove duplicate canonical identities.\n    out=[]\n    seen=set()\n    for ev in captured:\n        key=getattr(ev,"canonical_event_id",None) or getattr(ev,"provider_event_id",None) or repr(ev)\n        if key in seen: continue\n        seen.add(key); out.append(ev)\n\n    if not out:\n        tail=buf.getvalue()[-1500:]\n        raise RuntimeError(f"{league} promoted exact surface constructed zero CanonicalSportsEvent objects; output_tail={tail!r}")\n    return CanonicalProviderResult(league,tuple(out),len(out),"PROMOTED_BYTE_EXACT_PROVEN_SURFACE")\n\ndef acquire_canonical_events(league,timeout=15,root=None):\n    league=str(league).upper()\n    if league not in ADMITTED: raise RuntimeError(f"league not admitted: {league}")\n    if league in ("NFL","NCAAF","NBA"):\n        return _legacy(league,timeout)\n    return _promoted(league,timeout,root=root)\n'
TEST_SOURCE='\nfrom pathlib import Path\nimport json\nfrom qseries_v2.oracle_source_network.providers.uniform_sports_provider import acquire_canonical_events\n\nrows=[]\nfor league in ("NFL","NCAAF","NBA","NHL","MLS","EPL"):\n    r=acquire_canonical_events(league,timeout=15,root=Path.cwd())\n    assert r.event_count>0\n    assert r.execution_authority is False\n    sample=r.events[0]\n    print(f"[PROVIDER] {league} events={r.event_count} authority={r.authority}")\n    print(f"  [SAMPLE] id={getattr(sample,\'provider_event_id\',None)} home={getattr(sample,\'home\',getattr(sample,\'home_team\',None))} away={getattr(sample,\'away\',getattr(sample,\'away_team\',None))}")\n    rows.append({"league":league,"events":r.event_count,"authority":r.authority})\n\nstate=Path("qseries_v2/oracle_source_network/state/osn077_uniform_provider_contract.json")\nstate.write_text(json.dumps({"rows":rows,"execution_authority":False},indent=2),encoding="utf-8")\nprint("[STATE]",state)\nprint("[PASS] all six admitted leagues expose one acquire_canonical_events contract")\nprint("[PASS] NHL/MLS/EPL use promoted byte-exact proven surfaces")\nprint("[PASS] no certification subprocess used")\nprint("[PASS] OSN-077 uniform canonical sports provider contract rebuilt")\n'
